INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(2000, 'system', '/ˈsɪstəm/', 'noun', '{"zh-TW":["系統；體系"],"en":["a set of connected things forming a complex whole"]}', NULL, 'operating system / system failure / management system', '[{"en":"The new IT system improves efficiency.","zh-TW":"新的資訊系統提高了效率。"},{"en":"We implemented a quality management system.","zh-TW":"我們實施了品質管理系統。"}]', '{"noun":"system","adjective":"systematic, systemic","adverb":"systematically"}', NULL, 2, 2000),
(2001, 'table', '/ˈteɪbəl/', 'noun', '{"zh-TW":["【主要意義-名詞】桌子；表格","【次要意義-動詞（英式）】提出討論；將議題列入議程","【次要意義-動詞（美式）】擱置；延後討論"],"en":["[primary - noun] a piece of furniture with a flat top","[secondary - verb (British English)] to present something for discussion","[secondary - verb (American English)] to postpone discussion of something"]}', NULL, 'table a motion / table a proposal / table a discussion', '[{"en":"The committee tabled the budget proposal until next month. (AmE)","zh-TW":"委員會將預算提案延後到下個月討論。（美式）"},{"en":"The union tabled new wage demands at the meeting. (BrE)","zh-TW":"工會在會議上提出了新的薪資要求。（英式）"},{"en":"The issue was tabled for further review by the board.","zh-TW":"該議題被董事會擱置以供進一步審查。"}]', '{"noun":"tabling"}', '動詞 table 在美式和英式英語中意思相反！美式表示「擱置」，英式表示「提出」，TOEIC 考試以美式英語為主，此動詞常讓考生困惑。', 2, 2001),
(2002, 'tablet', '/ˈtæblɪt/', 'noun', '{"zh-TW":["平板電腦"],"en":["a flat portable computer with a touchscreen"]}', NULL, 'tablet computer / tablet screen', '[{"en":"She reads books on her tablet.","zh-TW":"她用平板電腦看書。"},{"en":"Tablets are popular for online learning.","zh-TW":"平板電腦在線上學習中很受歡迎。"}]', NULL, NULL, 2, 2002),
(2003, 'tackle', '/ˈtækl/', 'verb, noun', '{"zh-TW":["處理；解決","應對"],"en":["to deal with a difficult problem","equipment or an act of confronting"]}', NULL, 'tackle a problem / tackle the issue / tackle challenges', '[{"en":"We must tackle the issue of rising costs.","zh-TW":"我們必須處理成本上漲的問題。"},{"en":"The team tackled the project head-on.","zh-TW":"團隊直接面對這個專案。"}]', '{"noun":"tackle","verb":"tackle"}', NULL, 2, 2003),
(2004, 'tactics', '/ˈtæktɪks/', 'noun', '{"zh-TW":["策略；戰術"],"en":["planned actions to achieve a specific end"]}', NULL, 'marketing tactics / negotiation tactics / change tactics', '[{"en":"The sales team adopted new marketing tactics.","zh-TW":"銷售團隊採用了新的行銷策略。"},{"en":"Aggressive tactics may backfire.","zh-TW":"激進的策略可能會適得其反。"}]', '{"noun":"tactics, tactician","adjective":"tactical","adverb":"tactically"}', NULL, 3, 2004),
(2005, 'tailor', '/ˈteɪlər/', 'verb, noun', '{"zh-TW":["量身定做；裁剪","裁縫"],"en":["to make or adapt for a particular purpose","a person who makes clothes"]}', NULL, 'tailor-made / tailor to needs / tailor a solution', '[{"en":"We can tailor our services to your needs.","zh-TW":"我們可以根據您的需求量身定制服務。"},{"en":"The training program is tailored for new employees.","zh-TW":"培訓計畫是為新員工量身定制的。"}]', '{"noun":"tailor","verb":"tailor","adjective":"tailored"}', NULL, 2, 2005),
(2006, 'take', '/teɪk/', 'verb', '{"zh-TW":["拿；花費；採取"],"en":["to carry","to require time","to perform an action"]}', NULL, 'take action / take place', '[{"en":"We need to take action immediately.","zh-TW":"我們需要立即採取行動。"},{"en":"The conference takes place in March.","zh-TW":"會議在三月舉行。"}]', '{"verb":"take","noun":"takeover","noun2":"intake"}', NULL, 1, 2006),
(2007, 'talent', '/ˈtælənt/', 'noun', '{"zh-TW":["人才；才能"],"en":["natural aptitude; skilled people"]}', NULL, 'talent pool / talent acquisition / talented employees', '[{"en":"The company invests heavily in talent acquisition.","zh-TW":"公司大力投資人才招募。"},{"en":"Retaining top talent is a key challenge.","zh-TW":"留住頂尖人才是主要的挑戰。"}]', '{"noun":"talent","adjective":"talented"}', NULL, 2, 2007),
(2008, 'talk', '/tɔːk/', 'verb', '{"zh-TW":["說話；談論"],"en":["to speak","to discuss"]}', NULL, 'talk about / small talk', '[{"en":"Let''s talk about the budget.","zh-TW":"我們來談談預算。"},{"en":"He gave a talk on leadership.","zh-TW":"他做了一場關於領導力的演講。"}]', '{"verb":"talk","noun":"talk","noun2":"talker"}', NULL, 1, 2008),
(2009, 'tangible', '/ˈtændʒəbl/', 'adjective', '{"zh-TW":["有形的；實際的"],"en":["clear and definite; able to be touched"]}', NULL, 'tangible results / tangible assets / tangible benefits', '[{"en":"The training produced tangible results.","zh-TW":"培訓產生了實際的成果。"},{"en":"Tangible assets include buildings and equipment.","zh-TW":"有形資產包括建築物和設備。"}]', '{"noun":"tangibility","adjective":"tangible, intangible"}', NULL, 3, 2009),
(2010, 'target', '/ˈtɑːrɡɪt/', 'noun, verb', '{"zh-TW":["目標；對象","以...為目標"],"en":["an aim or objective","to direct at a particular group"]}', NULL, 'target market / target audience / meet the target', '[{"en":"We exceeded our sales target by 10%.","zh-TW":"我們超額完成了10%的銷售目標。"},{"en":"The campaign targets young professionals.","zh-TW":"該活動以年輕專業人士為目標對象。"}]', '{"noun":"target","verb":"target","adjective":"targeted"}', NULL, 2, 2010),
(2011, 'tariff', '/ˈtærɪf/', 'noun', '{"zh-TW":["關稅；稅率"],"en":["a tax on imported or exported goods"]}', NULL, 'import tariff / tariff barriers / impose tariffs', '[{"en":"The government imposed tariffs on imported steel.","zh-TW":"政府對進口鋼材徵收關稅。"},{"en":"Tariff reductions boosted international trade.","zh-TW":"關稅降低促進了國際貿易。"}]', '{"noun":"tariff"}', NULL, 2, 2011),
(2012, 'task', '/tæsk/', 'noun', '{"zh-TW":["任務；工作"],"en":["a piece of work to be done"]}', NULL, 'complete a task / task management / assign a task', '[{"en":"The manager assigned tasks to each team member.","zh-TW":"經理給每位團隊成員分配了任務。"},{"en":"Completing this task is our top priority.","zh-TW":"完成這項任務是我們的首要目標。"}]', '{"noun":"task","verb":"task"}', NULL, 1, 2012),
(2013, 'tax', '/tæks/', 'noun, verb', '{"zh-TW":["稅；稅金","課稅"],"en":["a compulsory payment to the government","to impose a tax on"]}', NULL, 'income tax / tax return / tax deduction', '[{"en":"The new tax policy benefits small businesses.","zh-TW":"新的稅務政策有利於小型企業。"},{"en":"Corporate profits are taxed at 20%.","zh-TW":"企業利潤按20%的稅率課稅。"}]', '{"noun":"tax, taxation, taxpayer","verb":"tax","adjective":"taxable"}', NULL, 1, 2013),
(2014, 'teach', '/tiːtʃ/', 'verb', '{"zh-TW":["教；教導"],"en":["to give lessons","to cause to learn"]}', NULL, 'teach a lesson / teach someone the ropes', '[{"en":"Experience teaches us valuable lessons.","zh-TW":"經驗教導我們寶貴的教訓。"},{"en":"She taught me the ropes when I joined.","zh-TW":"我剛加入時她教了我工作要領。"}]', '{"verb":"teach","noun":"teacher","noun2":"teaching"}', NULL, 2, 2014),
(2015, 'team', '/tiːm/', 'noun', '{"zh-TW":["團隊；小組"],"en":["a group working together"]}', NULL, 'team member / team building / team effort', '[{"en":"Effective teamwork is essential for success.","zh-TW":"有效的團隊合作對成功至關重要。"},{"en":"She leads a team of marketing specialists.","zh-TW":"她領導一個行銷專家團隊。"}]', '{"noun":"team, teamwork","verb":"team up"}', NULL, 1, 2015),
(2016, 'technical', '/ˈteknɪkl/', 'adjective', '{"zh-TW":["技術的；專業的"],"en":["relating to a particular subject or craft"]}', NULL, 'technical support / technical skills / technical issues', '[{"en":"We experienced some technical difficulties.","zh-TW":"我們遇到了一些技術問題。"},{"en":"The role requires strong technical skills.","zh-TW":"這個職位需要強大的技術技能。"}]', '{"noun":"technique, technology, technician","adjective":"technical","adverb":"technically"}', NULL, 3, 2016),
(2017, 'technique', '/tekˈniːk/', 'noun', '{"zh-TW":["技巧；技術；方法"],"en":["a way of carrying out a task"]}', NULL, 'management technique / new technique / effective technique', '[{"en":"New manufacturing techniques increased productivity.","zh-TW":"新的製造技術提高了生產力。"},{"en":"She learned various negotiation techniques.","zh-TW":"她學到了各種談判技巧。"}]', '{"noun":"technique","adjective":"technical"}', NULL, 3, 2017),
(2018, 'technology', '/tekˈnɑːlədʒi/', 'noun', '{"zh-TW":["技術；科技"],"en":["the application of scientific knowledge"]}', NULL, 'information technology / cutting-edge technology / adopt technology', '[{"en":"The company invested heavily in new technology.","zh-TW":"公司大力投資新技術。"},{"en":"Technology is transforming the workplace.","zh-TW":"科技正在改變工作場所。"}]', '{"noun":"technology, technologist","adjective":"technological"}', NULL, 4, 2018),
(2019, 'telephone', '/ˈtɛlɪfoʊn/', 'noun', '{"zh-TW":["電話"],"en":["a device for speaking to someone at a distance"]}', NULL, 'by telephone / telephone number', '[{"en":"You can reach us by telephone.","zh-TW":"你可以打電話聯繫我們。"},{"en":"Please leave your telephone number.","zh-TW":"請留下你的電話號碼。"}]', '{"noun":"telephone","verb":"telephone","noun2":"phone"}', NULL, 3, 2019),
(2020, 'temperature', '/ˈtemprətʃər/', 'noun', '{"zh-TW":["溫度"],"en":["the degree of heat or cold in a place"]}', '{"root":{"text":"temper","meaning":"mix/moderate (調節)"},"suffix":{"text":"-ature","meaning":"result (結果)"},"logic":"調節的結果狀態，即「溫度」。"}', 'room temperature / body temperature / high temperature', '[{"en":"The temperature dropped below zero last night.","zh-TW":"昨晚溫度降到零度以下。"},{"en":"What is the temperature outside?","zh-TW":"外面的溫度是多少？"}]', NULL, NULL, 4, 2020),
(2021, 'temporary', '/ˈtempəreri/', 'adjective', '{"zh-TW":["暫時的；臨時的"],"en":["lasting for a limited time"]}', NULL, 'temporary position / temporary solution / temporary worker', '[{"en":"This is only a temporary arrangement.","zh-TW":"這只是一個暫時的安排。"},{"en":"We hired temporary staff for the busy season.","zh-TW":"我們在旺季聘請了臨時員工。"}]', '{"noun":"temp","adjective":"temporary","adverb":"temporarily"}', NULL, 3, 2021),
(2022, 'tenant', '/ˈtenənt/', 'noun', '{"zh-TW":["租戶；承租人"],"en":["a person who occupies rented property"]}', NULL, 'tenant agreement / commercial tenant / existing tenant', '[{"en":"The building has several commercial tenants.","zh-TW":"這棟大樓有數個商業租戶。"},{"en":"Tenants must give 30 days'' notice before moving out.","zh-TW":"租戶搬出前須提前30天通知。"}]', '{"noun":"tenant, tenancy"}', NULL, 2, 2022),
(2023, 'tend', '/tend/', 'verb', '{"zh-TW":["傾向於；趨向"],"en":["to be likely to behave in a particular way"]}', NULL, 'tend to / tend toward / tendency', '[{"en":"Prices tend to rise during peak season.","zh-TW":"旺季期間價格往往會上漲。"},{"en":"Consumers tend to prefer eco-friendly products.","zh-TW":"消費者傾向於偏好環保產品。"}]', '{"noun":"tendency","verb":"tend"}', NULL, 1, 2023),
(2024, 'tender', '/ˈtendər/', 'noun, verb, adjective', '{"zh-TW":["投標；標書","投標","溫柔的；嫩的"],"en":["a formal offer to supply goods","to make a formal offer","gentle; soft"]}', NULL, 'submit a tender / tender process / invitation to tender', '[{"en":"Five companies submitted tenders for the project.","zh-TW":"五家公司為該專案提交了投標書。"},{"en":"The tender deadline is next Friday.","zh-TW":"投標截止日期是下週五。"}]', '{"noun":"tender","verb":"tender"}', NULL, 2, 2024),
(2025, 'tentative', '/ˈtentətɪv/', 'adjective', '{"zh-TW":["暫定的；試探性的"],"en":["not certain or fixed; provisional"]}', NULL, 'tentative agreement / tentative plan / tentative schedule', '[{"en":"We reached a tentative agreement on pricing.","zh-TW":"我們就定價達成了暫定協議。"},{"en":"The tentative launch date is in March.","zh-TW":"暫定的上市日期在三月。"}]', '{"adjective":"tentative","adverb":"tentatively"}', NULL, 3, 2025),
(2026, 'tenure', '/ˈtenjər/', 'noun', '{"zh-TW":["任期；任職期間"],"en":["the holding of an office or position"]}', NULL, 'during one''s tenure / job tenure / tenure track', '[{"en":"During her tenure, revenue doubled.","zh-TW":"在她任職期間，營收翻倍。"},{"en":"Average employee tenure at the company is five years.","zh-TW":"員工在公司的平均任期是五年。"}]', '{"noun":"tenure","adjective":"tenured"}', NULL, 2, 2026),
(2027, 'terminate', '/ˈtɜːrmɪneɪt/', 'verb', '{"zh-TW":["終止；結束"],"en":["to bring to an end"]}', NULL, 'terminate a contract / terminate employment / terminate an agreement', '[{"en":"Either party may terminate the contract with 30 days'' notice.","zh-TW":"任何一方均可提前30天通知終止合約。"},{"en":"His employment was terminated due to misconduct.","zh-TW":"他因不當行為而被解雇。"}]', '{"noun":"termination","verb":"terminate"}', NULL, 3, 2027),
(2028, 'territory', '/ˈterɪtɔːri/', 'noun', '{"zh-TW":["領土；區域","銷售區域"],"en":["an area of land; a region assigned to someone"]}', NULL, 'sales territory / expand into new territory / uncharted territory', '[{"en":"The sales rep covers the entire eastern territory.","zh-TW":"這位銷售代表負責整個東部區域。"},{"en":"We are expanding into new territory in Southeast Asia.","zh-TW":"我們正在東南亞拓展新領域。"}]', '{"noun":"territory","adjective":"territorial"}', NULL, 3, 2028),
(2029, 'testify', '/ˈtestɪfaɪ/', 'verb', '{"zh-TW":["作證；證明"],"en":["to give evidence as a witness"]}', NULL, 'testify in court / testify against / testify to', '[{"en":"The accountant testified in the fraud case.","zh-TW":"會計師在詐欺案中作證。"},{"en":"The results testify to the success of the program.","zh-TW":"結果證明了該計畫的成功。"}]', '{"noun":"testimony, testimonial","verb":"testify"}', NULL, 3, 2029),
(2030, 'testimony', '/ˈtɛstɪmoʊni/', 'noun', '{"zh-TW":["證詞"],"en":["a formal statement given in court"]}', NULL, 'give testimony / expert testimony', '[{"en":"Her testimony was crucial to the case.","zh-TW":"她的證詞對案件至關重要。"},{"en":"He gave testimony before Congress.","zh-TW":"他在國會前作證。"}]', '{"verb":"testify"}', NULL, 3, 2030),
(2031, 'textbook', '/ˈtɛkstbʊk/', 'noun', '{"zh-TW":["教科書"],"en":["a book used for studying a subject"]}', NULL, 'textbook example / buy textbooks', '[{"en":"Textbooks are expensive.","zh-TW":"教科書很貴。"},{"en":"This is a textbook example of good design.","zh-TW":"這是好設計的典型範例。"}]', NULL, NULL, 3, 2031),
(2032, 'theater', '/ˈθiːətər/', 'noun', '{"zh-TW":["劇院；戲劇"],"en":["a building for performances","the art of writing and performing plays"]}', '{"root":{"text":"thea","meaning":"view (觀看)"},"suffix":{"text":"-ter","meaning":"place (場所)"},"logic":"觀看表演的場所，即「劇院」。"}', 'movie theater / theater performance', '[{"en":"We saw a play at the local theater.","zh-TW":"我們在當地劇院看了一場戲。"},{"en":"She studied theater in college.","zh-TW":"她在大學主修戲劇。"}]', '{"adjective":"theatrical"}', NULL, 3, 2032),
(2033, 'thesis', '/ˈθiːsɪs/', 'noun', '{"zh-TW":["論文；論點"],"en":["a long essay for a degree","a theory to be proved","a long piece of writing for a degree"]}', NULL, 'master''s thesis / central thesis; master''s thesis / thesis statement', '[{"en":"Her master''s thesis focused on supply chain efficiency.","zh-TW":"她的碩士論文專注於供應鏈效率。"},{"en":"The central thesis of the report is cost reduction.","zh-TW":"報告的核心論點是成本削減。"},{"en":"She''s writing her master''s thesis.","zh-TW":"她正在寫碩士論文。"},{"en":"Your thesis statement should be clear.","zh-TW":"你的論點應該要清楚。"}]', '{"noun":"thesis","plural":"theses"}', NULL, 2, 2033),
(2034, 'thorough', '/ˈθʌroʊ/', 'adjective', '{"zh-TW":["徹底的；詳盡的"],"en":["complete with attention to every detail"]}', NULL, 'thorough investigation / thorough review / thorough analysis', '[{"en":"We conducted a thorough investigation.","zh-TW":"我們進行了徹底的調查。"},{"en":"The report requires a more thorough analysis.","zh-TW":"這份報告需要更詳盡的分析。"}]', '{"adjective":"thorough","adverb":"thoroughly","noun":"thoroughness"}', NULL, 3, 2034),
(2035, 'threat', '/θret/', 'noun', '{"zh-TW":["威脅；恐嚇"],"en":["a statement of intention to harm; a danger"]}', NULL, 'pose a threat / security threat / under threat', '[{"en":"Cybersecurity threats are increasing globally.","zh-TW":"全球網路安全威脅正在增加。"},{"en":"Climate change poses a serious threat to businesses.","zh-TW":"氣候變遷對企業構成嚴重威脅。"}]', '{"noun":"threat","verb":"threaten","adjective":"threatening"}', NULL, 2, 2035),
(2036, 'threshold', '/ˈθreʃhoʊld/', 'noun', '{"zh-TW":["門檻；起始點"],"en":["the level at which something starts"]}', NULL, 'tax threshold / below the threshold / pain threshold', '[{"en":"Income below the threshold is tax-free.","zh-TW":"低於門檻的收入免稅。"},{"en":"The company has reached the profitability threshold.","zh-TW":"公司已達到盈利門檻。"}]', '{"noun":"threshold"}', NULL, 3, 2036),
(2037, 'thrive', '/θraɪv/', 'verb', '{"zh-TW":["蓬勃發展；興旺"],"en":["to grow or develop well"]}', NULL, 'thrive in / thrive on / thriving business', '[{"en":"Small businesses thrived during the digital boom.","zh-TW":"小型企業在數位化潮流中蓬勃發展。"},{"en":"She thrives under pressure.","zh-TW":"她在壓力下表現出色。"}]', '{"verb":"thrive","adjective":"thriving"}', NULL, 2, 2037),
(2038, 'thunder', '/ˈθʌndər/', 'noun', '{"zh-TW":["雷聲"],"en":["the loud sound following lightning"]}', '{"root":{"text":"thunder","meaning":"resound (回響)"},"logic":"源自古英語 þunor（巨響）。"}', 'thunder and lightning / thunderstorm', '[{"en":"We heard thunder in the distance.","zh-TW":"我們聽到遠處的雷聲。"},{"en":"The dog is afraid of thunder.","zh-TW":"這隻狗怕打雷。"}]', '{"noun":"thunderstorm","adjective":"thunderous"}', NULL, 3, 2038),
(2039, 'tight', '/taɪt/', 'adjective', '{"zh-TW":["緊的；嚴格的","資金緊張的"],"en":["fixed or held firmly","limited or restricted"]}', NULL, 'tight deadline / tight budget / tight schedule', '[{"en":"We are working under a very tight deadline.","zh-TW":"我們在非常緊迫的截止日期下工作。"},{"en":"The budget is tight this quarter.","zh-TW":"本季度預算緊張。"}]', '{"adjective":"tight","adverb":"tightly","verb":"tighten"}', NULL, 2, 2039),
(2040, 'timely', '/ˈtaɪmli/', 'adjective', '{"zh-TW":["及時的；適時的"],"en":["done at a suitable or opportune time"]}', NULL, 'timely manner / timely delivery / timely response', '[{"en":"Please respond in a timely manner.","zh-TW":"請及時回覆。"},{"en":"Timely delivery is crucial for customer satisfaction.","zh-TW":"及時交貨對客戶滿意度至關重要。"}]', '{"adjective":"timely","noun":"timeliness"}', NULL, 2, 2040),
(2041, 'tolerance', '/ˈtɑːlərəns/', 'noun', '{"zh-TW":["容忍；寬容","公差"],"en":["willingness to accept differences","the allowable variation"]}', NULL, 'zero tolerance / risk tolerance / tolerance level', '[{"en":"The company has a zero-tolerance policy on harassment.","zh-TW":"公司對騷擾採取零容忍政策。"},{"en":"Investors have different levels of risk tolerance.","zh-TW":"投資者有不同程度的風險承受力。"}]', '{"noun":"tolerance","verb":"tolerate","adjective":"tolerant, tolerable"}', NULL, 3, 2041),
(2042, 'tolerant', '/ˈtɒlərənt/', 'adjective', '{"zh-TW":["容忍的；寬容的"],"en":["willing to accept views or behavior different from one''s own"]}', '{"root":{"text":"toler","meaning":"endure (忍受)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能忍受差異的，即「寬容的」。"}', 'tolerant of / tolerant society', '[{"en":"We should be tolerant of different opinions.","zh-TW":"我們應該容忍不同的意見。"},{"en":"She is very tolerant of her coworkers.","zh-TW":"她對同事很寬容。"}]', '{"noun":"tolerance","verb":"tolerate"}', NULL, 3, 2042),
(2043, 'tool', '/tuːl/', 'noun', '{"zh-TW":["工具；手段"],"en":["a device or implement used for a task"]}', NULL, 'management tool / software tool / essential tool', '[{"en":"Data analytics is an essential business tool.","zh-TW":"數據分析是重要的商業工具。"},{"en":"The new software tool streamlines our workflow.","zh-TW":"新的軟體工具簡化了我們的工作流程。"}]', '{"noun":"tool, toolkit"}', NULL, 1, 2043),
(2044, 'topic', '/ˈtɑːpɪk/', 'noun', '{"zh-TW":["主題；話題"],"en":["a matter dealt with in discussion"]}', NULL, 'on topic / hot topic / change the topic', '[{"en":"Sustainability is a hot topic in business today.","zh-TW":"永續性是當今商業的熱門話題。"},{"en":"Let''s stay on topic during the meeting.","zh-TW":"讓我們在會議中保持主題不偏離。"}]', '{"noun":"topic","adjective":"topical"}', NULL, 2, 2044),
(2045, 'tornado', '/tɔːrˈneɪdoʊ/', 'noun', '{"zh-TW":["龍捲風"],"en":["a violently rotating column of air"]}', '{"root":{"text":"tornado","meaning":"turn (旋轉)"},"logic":"源自西班牙語 tornar（轉），指旋轉的風柱。"}', 'tornado warning / tornado alley', '[{"en":"The tornado destroyed dozens of houses.","zh-TW":"龍捲風摧毀了數十棟房屋。"},{"en":"Tornado warnings were issued for the entire county.","zh-TW":"全縣發布了龍捲風警報。"}]', NULL, NULL, 3, 2045),
(2046, 'total', '/ˈtoʊtl/', 'noun, adjective, verb', '{"zh-TW":["總計；全部的","合計"],"en":["the complete amount","to amount to"]}', NULL, 'in total / total cost / total revenue', '[{"en":"The total cost of the project is $2 million.","zh-TW":"專案總成本為兩百萬美元。"},{"en":"Sales totaled $5 million this quarter.","zh-TW":"本季銷售額合計五百萬美元。"}]', '{"noun":"total, totality","adjective":"total","adverb":"totally","verb":"total"}', NULL, 2, 2046),
(2047, 'tournament', '/ˈtɜːrnəmənt/', 'noun', '{"zh-TW":["錦標賽；比賽"],"en":["a competition with many games"]}', NULL, 'tennis tournament / enter a tournament', '[{"en":"She entered the tennis tournament.","zh-TW":"她參加了網球錦標賽。"},{"en":"The tournament lasts two weeks.","zh-TW":"比賽持續兩週。"}]', NULL, NULL, 4, 2047),
(2048, 'trace', '/treɪs/', 'noun, verb', '{"zh-TW":["痕跡；蹤跡","追蹤；追溯"],"en":["a mark or sign of something","to find or follow"]}', NULL, 'trace back to / without a trace / trace the origin', '[{"en":"We traced the error back to a software bug.","zh-TW":"我們將錯誤追溯到一個軟體漏洞。"},{"en":"There is no trace of the missing shipment.","zh-TW":"失蹤的貨物沒有任何蹤跡。"}]', '{"noun":"trace, traceability","verb":"trace","adjective":"traceable"}', NULL, 2, 2048),
(2049, 'track', '/træk/', 'noun, verb', '{"zh-TW":["軌道；途徑","追蹤；跟蹤"],"en":["a path or course","to follow the progress of"]}', NULL, 'keep track of / track record / on track', '[{"en":"We need to keep track of all expenses.","zh-TW":"我們需要追蹤所有費用。"},{"en":"The project is on track for completion in June.","zh-TW":"專案按計畫將在六月完成。"}]', '{"noun":"track, tracker, tracking","verb":"track"}', NULL, 2, 2049);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(2050, 'trade', '/treɪd/', 'noun, verb', '{"zh-TW":["貿易；交易","交易；經商"],"en":["the buying and selling of goods","to engage in commerce"]}', NULL, 'international trade / trade agreement / free trade', '[{"en":"International trade expanded rapidly last year.","zh-TW":"去年國際貿易迅速擴張。"},{"en":"The two countries signed a free trade agreement.","zh-TW":"兩國簽署了自由貿易協定。"}]', '{"noun":"trade, trader, trading","verb":"trade"}', NULL, 2, 2050),
(2051, 'trademark', '/ˈtreɪdmɑːrk/', 'noun', '{"zh-TW":["商標"],"en":["a symbol or name legally registered for a product"]}', NULL, 'registered trademark / trademark infringement', '[{"en":"Our logo is a registered trademark.","zh-TW":"我們的商標已經註冊。"},{"en":"Trademark infringement can lead to lawsuits.","zh-TW":"商標侵權可能導致訴訟。"}]', '{"noun":"trademark","verb":"trademark","adjective":"trademarked"}', NULL, 3, 2051),
(2052, 'tradition', '/trəˈdɪʃn/', 'noun', '{"zh-TW":["傳統","傳統；慣例"],"en":["a custom or belief passed through generations","a long-established custom or belief"]}', '{"prefix":{"text":"tra-","meaning":"across (跨越)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"跨越世代傳遞下來的東西，即「傳統」。"}', 'cultural tradition / family tradition; long tradition / by tradition / break with tradition', '[{"en":"It is a tradition to eat turkey on Thanksgiving.","zh-TW":"感恩節吃火雞是一項傳統。"},{"en":"We should respect local traditions.","zh-TW":"我們應該尊重當地傳統。"},{"en":"The company has a long tradition of innovation.","zh-TW":"公司有悠久的創新傳統。"},{"en":"They broke with tradition and appointed a young CEO.","zh-TW":"他們打破傳統任命了一位年輕的執行長。"}]', '{"adjective":"traditional","adverb":"traditionally","noun":"tradition"}', NULL, 3, 2052),
(2053, 'traffic', '/ˈtræfɪk/', 'noun', '{"zh-TW":["交通；流量"],"en":["vehicles moving on roads; the amount of data"]}', NULL, 'web traffic / traffic congestion / traffic flow', '[{"en":"Website traffic increased by 40% after the campaign.","zh-TW":"活動後網站流量增加了40%。"},{"en":"Heavy traffic caused delays for commuters.","zh-TW":"交通擁堵導致通勤者延誤。"}]', '{"noun":"traffic"}', NULL, 3, 2053),
(2054, 'trait', '/treɪt/', 'noun', '{"zh-TW":["特徵；特點"],"en":["a distinguishing quality or characteristic"]}', NULL, 'personality trait / key trait / leadership trait', '[{"en":"Adaptability is a key trait for managers.","zh-TW":"適應力是管理者的關鍵特質。"},{"en":"The company values creativity as a core trait.","zh-TW":"公司將創造力視為核心特質。"}]', '{"noun":"trait"}', NULL, 2, 2054),
(2055, 'transaction', '/trænˈzækʃn/', 'noun', '{"zh-TW":["交易；事務"],"en":["an instance of buying or selling"]}', NULL, 'financial transaction / online transaction / transaction fee', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"There is a small fee per transaction.","zh-TW":"每筆交易有少量手續費。"}]', '{"noun":"transaction","adjective":"transactional"}', NULL, 4, 2055),
(2056, 'transcript', '/ˈtrænskrɪpt/', 'noun', '{"zh-TW":["成績單；謄本"],"en":["an official record of a student''s grades"]}', NULL, 'official transcript / academic transcript', '[{"en":"Send your official transcript to the school.","zh-TW":"將你的正式成績單寄到學校。"},{"en":"The transcript shows all courses taken.","zh-TW":"成績單顯示所有修過的課程。"}]', NULL, NULL, 4, 2056),
(2057, 'transfer', '/ˈtrænsfɜːr/', 'noun, verb', '{"zh-TW":["轉移；調動","轉移；轉讓"],"en":["the act of moving something","to move from one place to another"]}', NULL, 'transfer funds / knowledge transfer / transfer to', '[{"en":"She transferred to the London office.","zh-TW":"她調到了倫敦辦公室。"},{"en":"Please transfer the funds to this account.","zh-TW":"請將資金轉入此帳戶。"}]', '{"noun":"transfer, transference","verb":"transfer","adjective":"transferable"}', NULL, 3, 2057),
(2058, 'transform', '/trænsˈfɔːrm/', 'verb', '{"zh-TW":["轉變；改造"],"en":["to change completely in form or character"]}', '{"prefix":{"text":"trans-","meaning":"across (跨越)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"跨越到另一種形態，即「轉變」。"}', 'transform into / digital transformation; digital transformation / transform the business / transform into', '[{"en":"Technology has transformed the way we work.","zh-TW":"科技改變了我們的工作方式。"},{"en":"The city has been transformed in recent years.","zh-TW":"這座城市近年來已經蛻變。"},{"en":"The company is undergoing a digital transformation.","zh-TW":"公司正在進行數位轉型。"}]', '{"noun":"transformation","adjective":"transformative","verb":"transform"}', NULL, 3, 2058),
(2059, 'transition', '/trænˈzɪʃn/', 'noun, verb', '{"zh-TW":["過渡；轉型","過渡；轉變"],"en":["the process of changing from one state to another","to change"]}', NULL, 'smooth transition / transition period / transition to', '[{"en":"The transition to the new system took three months.","zh-TW":"過渡到新系統花了三個月。"},{"en":"We need to ensure a smooth transition.","zh-TW":"我們需要確保順利的過渡。"}]', '{"noun":"transition","verb":"transition","adjective":"transitional"}', NULL, 4, 2059),
(2060, 'transmit', '/trænzˈmɪt/', 'verb', '{"zh-TW":["傳送；傳輸"],"en":["to send or pass on from one place to another"]}', NULL, 'transmit data / transmit information / transmit electronically', '[{"en":"The system transmits data in real time.","zh-TW":"系統即時傳輸數據。"},{"en":"Reports are transmitted electronically to headquarters.","zh-TW":"報告以電子方式傳送到總部。"}]', '{"noun":"transmission, transmitter","verb":"transmit"}', NULL, 3, 2060),
(2061, 'transparent', '/trænsˈpærənt/', 'adjective', '{"zh-TW":["透明的；公開的"],"en":["open and honest; easy to see through"]}', NULL, 'transparent process / transparent pricing / fully transparent', '[{"en":"The company maintains transparent accounting practices.","zh-TW":"公司維持透明的會計慣例。"},{"en":"We believe in transparent communication with stakeholders.","zh-TW":"我們相信與利害關係人的透明溝通。"}]', '{"noun":"transparency","adjective":"transparent","adverb":"transparently"}', NULL, 4, 2061),
(2062, 'transport', '/ˈtrænspɔːrt/', 'noun, verb', '{"zh-TW":["運輸；交通工具","運輸；運送"],"en":["the movement of goods or people","to carry from one place to another"]}', NULL, 'public transport / transport goods / transport costs', '[{"en":"Transport costs have risen significantly.","zh-TW":"運輸成本大幅上升。"},{"en":"Goods are transported by truck and rail.","zh-TW":"貨物透過卡車和鐵路運輸。"}]', '{"noun":"transport, transportation","verb":"transport"}', NULL, 3, 2062),
(2063, 'treaty', '/ˈtriːti/', 'noun', '{"zh-TW":["條約"],"en":["a formal agreement between countries"]}', NULL, 'peace treaty / sign a treaty', '[{"en":"The two countries signed a peace treaty.","zh-TW":"兩國簽署了和平條約。"},{"en":"The treaty was ratified by both nations.","zh-TW":"條約被兩國批准。"}]', NULL, NULL, 2, 2063),
(2064, 'trend', '/trend/', 'noun', '{"zh-TW":["趨勢；動向"],"en":["a general direction of change"]}', NULL, 'market trend / upward trend / follow a trend', '[{"en":"The trend toward remote work is accelerating.","zh-TW":"遠端工作的趨勢正在加速。"},{"en":"Market trends indicate growing consumer confidence.","zh-TW":"市場趨勢顯示消費者信心增長。"}]', '{"noun":"trend","adjective":"trending, trendy"}', NULL, 2, 2064),
(2065, 'trigger', '/ˈtrɪɡər/', 'noun, verb', '{"zh-TW":["觸發因素","觸發；引起"],"en":["something that causes an event","to cause something to happen"]}', NULL, 'trigger a response / trigger growth / trigger an alert', '[{"en":"The announcement triggered a sell-off in the market.","zh-TW":"該公告引發了市場拋售。"},{"en":"Rising costs triggered a review of the budget.","zh-TW":"成本上升觸發了對預算的審查。"}]', '{"noun":"trigger","verb":"trigger"}', NULL, 3, 2065),
(2066, 'trim', '/trɪm/', 'verb, noun', '{"zh-TW":["削減；修剪","修剪"],"en":["to reduce by cutting; to make neat","an act of cutting"]}', NULL, 'trim costs / trim the budget / trim expenses', '[{"en":"The company trimmed its workforce by 10%.","zh-TW":"公司裁減了10%的員工。"},{"en":"We need to trim unnecessary expenses.","zh-TW":"我們需要削減不必要的支出。"}]', '{"noun":"trim","verb":"trim"}', NULL, 1, 2066),
(2067, 'triple', '/ˈtrɪpl/', 'adjective, verb', '{"zh-TW":["三倍的","增至三倍"],"en":["consisting of three parts","to become three times as much"]}', NULL, 'triple the amount / triple in value / triple digits', '[{"en":"Revenue tripled in just two years.","zh-TW":"營收在短短兩年內增長了三倍。"},{"en":"The company achieved triple-digit growth.","zh-TW":"公司實現了三位數的增長。"}]', '{"adjective":"triple","verb":"triple"}', NULL, 2, 2067),
(2068, 'triumph', '/ˈtraɪʌmf/', 'noun, verb', '{"zh-TW":["勝利；成就","獲勝"],"en":["a great victory or achievement","to achieve victory"]}', NULL, 'triumph over / a triumph of / personal triumph', '[{"en":"The product launch was a triumph for the team.","zh-TW":"產品發布是團隊的一大勝利。"},{"en":"The company triumphed over its competitors.","zh-TW":"公司戰勝了競爭對手。"}]', '{"noun":"triumph","verb":"triumph","adjective":"triumphant"}', NULL, 3, 2068),
(2069, 'trophy', '/ˈtroʊfi/', 'noun', '{"zh-TW":["獎盃"],"en":["a prize given to the winner"]}', NULL, 'trophy cabinet / lift the trophy', '[{"en":"The captain lifted the trophy.","zh-TW":"隊長舉起了獎盃。"},{"en":"They added another trophy to their collection.","zh-TW":"他們的收藏中又多了一座獎盃。"}]', NULL, NULL, 2, 2069),
(2070, 'tropical', '/ˈtrɒpɪkl/', 'adjective', '{"zh-TW":["熱帶的"],"en":["relating to the tropics; very hot and humid"]}', '{"root":{"text":"tropic","meaning":"turn (轉向)"},"suffix":{"text":"-al","meaning":"relating to (相關的)"},"logic":"源自太陽在回歸線「轉向」，指熱帶地區的。"}', 'tropical storm / tropical climate / tropical fruit', '[{"en":"Tropical storms are common in this region.","zh-TW":"熱帶風暴在這個地區很常見。"},{"en":"Bananas grow in tropical climates.","zh-TW":"香蕉生長在熱帶氣候中。"}]', '{"noun":"tropics"}', NULL, 3, 2070),
(2071, 'troubleshoot', '/ˈtrʌblʃuːt/', 'verb', '{"zh-TW":["排除故障；解決問題"],"en":["to identify and solve problems"]}', NULL, 'troubleshoot issues / troubleshoot a system / troubleshooting guide', '[{"en":"The IT team is troubleshooting the network issue.","zh-TW":"IT團隊正在排除網路故障。"},{"en":"Please refer to the troubleshooting guide.","zh-TW":"請參閱故障排除指南。"}]', '{"noun":"troubleshooting, troubleshooter","verb":"troubleshoot"}', NULL, 4, 2071),
(2072, 'trust', '/trʌst/', 'noun, verb', '{"zh-TW":["信任；信託","信任；相信"],"en":["firm belief in reliability","to believe in the honesty of"]}', NULL, 'build trust / trust fund / mutual trust', '[{"en":"Building trust with customers takes time.","zh-TW":"與客戶建立信任需要時間。"},{"en":"We trust our suppliers to deliver on time.","zh-TW":"我們相信供應商會準時交貨。"}]', '{"noun":"trust, trustee","verb":"trust","adjective":"trustworthy, trusted"}', NULL, 2, 2072),
(2073, 'tsunami', '/tsuːˈnɑːmi/', 'noun', '{"zh-TW":["海嘯"],"en":["a very large ocean wave caused by an earthquake"]}', '{"root":{"text":"tsu-nami","meaning":"harbor wave (港灣的波浪)"},"logic":"源自日語「津波」（港灣的波浪）。"}', 'tsunami warning / trigger a tsunami', '[{"en":"The earthquake triggered a massive tsunami.","zh-TW":"地震引發了一場巨大的海嘯。"},{"en":"Coastal residents were evacuated after the tsunami warning.","zh-TW":"海嘯警報後沿海居民被疏散。"}]', NULL, NULL, 3, 2073),
(2074, 'tuition', '/tjuːˈɪʃən/', 'noun', '{"zh-TW":["學費；教學","學費"],"en":["money paid for instruction","teaching","the money paid for being taught"]}', NULL, 'tuition fee / tuition reimbursement; tuition fee / tuition waiver', '[{"en":"The company offers tuition reimbursement.","zh-TW":"公司提供學費補助。"},{"en":"Tuition fees have increased by 5%.","zh-TW":"學費上漲了5%。"},{"en":"Tuition costs keep rising.","zh-TW":"學費持續上漲。"},{"en":"She received a tuition waiver.","zh-TW":"她獲得了學費減免。"}]', '{"noun":"tuition"}', NULL, 3, 2074),
(2075, 'turnout', '/ˈtɜːrnaʊt/', 'noun', '{"zh-TW":["出席人數；參與率"],"en":["the number of people attending an event"]}', NULL, 'high turnout / voter turnout / expected turnout', '[{"en":"The conference had a higher turnout than expected.","zh-TW":"會議的出席人數超出預期。"},{"en":"Voter turnout was at an all-time high.","zh-TW":"投票率創下歷史新高。"}]', '{"noun":"turnout"}', NULL, 3, 2075),
