(2077, 'turnround', '/ˈtɜːrnəraʊnd/', 'noun', '{"zh-TW":["週轉時間；好轉"],"en":["the time needed to complete a process; a recovery"]}', NULL, 'quick turnaround / turnaround time / business turnaround', '[{"en":"The turnaround time for orders is 48 hours.","zh-TW":"訂單的週轉時間為48小時。"},{"en":"The new CEO achieved a remarkable business turnaround.","zh-TW":"新任執行長實現了顯著的業務好轉。"}]', '{"noun":"turnaround"}', NULL, 3, 2077),
(2078, 'tutor', '/ˈtjuːtər/', 'noun', '{"zh-TW":["家教；導師","輔導"],"en":["a private teacher","to teach individually"]}', NULL, 'private tutor / math tutor; private tutor / tutor sessions / peer tutor', '[{"en":"She hired a math tutor.","zh-TW":"她請了一位數學家教。"},{"en":"The tutor helped him pass the exam.","zh-TW":"家教幫他通過了考試。"},{"en":"She hired a tutor to improve her English.","zh-TW":"她聘請了一位家教來提升英文。"},{"en":"Senior staff tutor new employees during onboarding.","zh-TW":"資深員工在入職期間輔導新員工。"}]', '{"verb":"tutor","noun2":"tutoring","noun":"tutor, tutorial, tutoring"}', NULL, 2, 2078),
(2079, 'typhoon', '/taɪˈfuːn/', 'noun', '{"zh-TW":["颱風"],"en":["a tropical storm in the western Pacific"]}', '{"root":{"text":"typhoon","meaning":"great wind (大風)"},"logic":"源自中文「大風」或阿拉伯語 tufan。"}', 'typhoon season / typhoon warning', '[{"en":"The typhoon brought heavy rain and strong winds.","zh-TW":"颱風帶來暴雨和強風。"},{"en":"All flights were cancelled due to the typhoon.","zh-TW":"所有航班因颱風取消。"}]', NULL, NULL, 3, 2079),
(2080, 'typical', '/ˈtɪpɪkl/', 'adjective', '{"zh-TW":["典型的；代表性的"],"en":["having the distinctive qualities of a type"]}', NULL, 'typical example / typical day / typical customer', '[{"en":"A typical workday starts at 9 AM.","zh-TW":"典型的工作日從上午9點開始。"},{"en":"This is a typical example of market fluctuation.","zh-TW":"這是市場波動的典型例子。"}]', '{"adjective":"typical","adverb":"typically"}', NULL, 3, 2080),
(2081, 'ultimate', '/ˈʌltɪmət/', 'adjective', '{"zh-TW":["最終的；終極的"],"en":["being the final or fundamental"]}', NULL, 'ultimate goal / ultimate decision / ultimate responsibility', '[{"en":"Our ultimate goal is customer satisfaction.","zh-TW":"我們的最終目標是客戶滿意。"},{"en":"The CEO has ultimate responsibility for the decision.","zh-TW":"執行長對這個決定承擔最終責任。"}]', '{"adjective":"ultimate","adverb":"ultimately","noun":"ultimatum"}', NULL, 3, 2081),
(2082, 'unanimous', '/juːˈnænɪməs/', 'adjective', '{"zh-TW":["一致的；無異議的"],"en":["fully in agreement"]}', NULL, 'unanimous decision / unanimous vote / unanimous support', '[{"en":"The board made a unanimous decision to proceed.","zh-TW":"董事會一致決定繼續進行。"},{"en":"The proposal received unanimous support.","zh-TW":"該提案獲得了一致支持。"}]', '{"noun":"unanimity","adjective":"unanimous","adverb":"unanimously"}', NULL, 3, 2082),
(2083, 'underestimate', '/ˌʌndərˈestɪmeɪt/', 'verb', '{"zh-TW":["低估"],"en":["to estimate as less than the actual value"]}', NULL, 'underestimate the cost / underestimate the risk / never underestimate', '[{"en":"Never underestimate the importance of customer feedback.","zh-TW":"永遠不要低估客戶回饋的重要性。"},{"en":"We underestimated the project timeline.","zh-TW":"我們低估了專案的時程。"}]', '{"noun":"underestimation","verb":"underestimate"}', NULL, 5, 2083),
(2084, 'undergo', '/ˌʌndərˈɡoʊ/', 'verb', '{"zh-TW":["經歷；接受"],"en":["to experience or be subjected to"]}', NULL, 'undergo changes / undergo training / undergo surgery', '[{"en":"The company is undergoing major restructuring.","zh-TW":"公司正在經歷重大重組。"},{"en":"All employees must undergo safety training.","zh-TW":"所有員工都必須接受安全訓練。"}]', '{"verb":"undergo"}', NULL, 3, 2084),
(2085, 'undergraduate', '/ˌʌndərˈɡrædʒuɪt/', 'noun', '{"zh-TW":["大學生；本科生","大學生"],"en":["a university student who has not yet received a first degree","a student studying for a first degree"]}', NULL, 'undergraduate degree / undergraduate program; undergraduate program / undergraduate student', '[{"en":"She completed her undergraduate degree in economics.","zh-TW":"她完成了經濟學的學士學位。"},{"en":"We recruit from top undergraduate programs.","zh-TW":"我們從頂尖大學課程招聘。"},{"en":"She''s an undergraduate at Oxford.","zh-TW":"她是牛津大學的大學生。"},{"en":"The undergraduate program lasts four years.","zh-TW":"大學學程為期四年。"}]', '{"noun":"undergraduate","adjective":"undergraduate"}', NULL, 5, 2085),
(2086, 'underline', '/ˌʌndərˈlaɪn/', 'verb', '{"zh-TW":["強調；突顯"],"en":["to emphasize; to draw attention to"]}', NULL, 'underline the importance / underline the need', '[{"en":"The report underlines the need for investment.","zh-TW":"報告強調了投資的必要性。"},{"en":"Recent events underline the importance of planning.","zh-TW":"近期事件突顯了規劃的重要性。"}]', '{"verb":"underline"}', NULL, 3, 2086),
(2087, 'undermine', '/ˌʌndərˈmaɪn/', 'verb', '{"zh-TW":["破壞；削弱"],"en":["to weaken or damage gradually"]}', NULL, 'undermine confidence / undermine authority / undermine efforts', '[{"en":"The scandal undermined public confidence.","zh-TW":"醜聞破壞了公眾信心。"},{"en":"Internal conflicts undermine team productivity.","zh-TW":"內部衝突削弱了團隊生產力。"}]', '{"verb":"undermine"}', NULL, 3, 2087),
(2088, 'undertake', '/ˌʌndərˈteɪk/', 'verb', '{"zh-TW":["承擔；從事"],"en":["to commit to doing something"]}', NULL, 'undertake a project / undertake research / undertake responsibility', '[{"en":"We undertook a comprehensive market study.","zh-TW":"我們進行了全面的市場研究。"},{"en":"The firm undertook the renovation project.","zh-TW":"該公司承擔了翻新工程。"}]', '{"noun":"undertaking","verb":"undertake"}', NULL, 3, 2088),
(2089, 'underway', '/ˌʌndərˈweɪ/', 'adjective, adverb', '{"zh-TW":["進行中的"],"en":["having started and in progress"]}', NULL, 'get underway / already underway / well underway', '[{"en":"Construction is already underway at the new site.","zh-TW":"新址的建設已經在進行中。"},{"en":"Plans are well underway for the expansion.","zh-TW":"擴張計畫正在順利進行中。"}]', '{"adjective":"underway"}', NULL, 3, 2089),
(2090, 'underwrite', '/ˌʌndərˈraɪt/', 'verb', '{"zh-TW":["承保；擔保"],"en":["to accept financial responsibility for","to insure"]}', NULL, 'underwrite a loan / underwrite an IPO', '[{"en":"The bank agreed to underwrite the bond issue.","zh-TW":"銀行同意承銷債券發行。"},{"en":"Insurance companies underwrite risk.","zh-TW":"保險公司承保風險。"}]', '{"verb":"underwrite","noun":"underwriter","noun2":"underwriting"}', NULL, 4, 2090),
(2091, 'unemployment', '/ˌʌnɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["失業；失業率"],"en":["the state of being without a job"]}', NULL, 'unemployment rate / unemployment benefits / reduce unemployment', '[{"en":"The unemployment rate dropped to 4%.","zh-TW":"失業率降至4%。"},{"en":"Government programs aim to reduce unemployment.","zh-TW":"政府計畫旨在降低失業率。"}]', '{"noun":"unemployment, employment","adjective":"unemployed, employed","verb":"employ"}', NULL, 4, 2091),
(2092, 'unforeseen', '/ˌʌnfɔːrˈsiːn/', 'adjective', '{"zh-TW":["無法預見的；意外的"],"en":["not anticipated or predicted"]}', NULL, 'unforeseen circumstances / unforeseen problems / unforeseen delays', '[{"en":"Unforeseen circumstances caused the project delay.","zh-TW":"不可預見的情況導致專案延遲。"},{"en":"We must prepare for unforeseen risks.","zh-TW":"我們必須為不可預見的風險做準備。"}]', '{"adjective":"unforeseen, foreseen","verb":"foresee"}', NULL, 4, 2092),
(2093, 'uniform', '/ˈjuːnɪfɔːrm/', 'adjective, noun', '{"zh-TW":["統一的；一致的","制服"],"en":["consistent; not varying","a distinctive set of clothes"]}', NULL, 'uniform standard / uniform policy / uniform across', '[{"en":"The company enforces uniform quality standards.","zh-TW":"公司執行統一的品質標準。"},{"en":"Pricing must be uniform across all regions.","zh-TW":"定價在所有地區必須一致。"}]', '{"noun":"uniform, uniformity","adjective":"uniform","adverb":"uniformly"}', NULL, 3, 2093),
(2094, 'unique', '/juːˈniːk/', 'adjective', '{"zh-TW":["獨特的；唯一的"],"en":["being the only one of its kind"]}', NULL, 'unique opportunity / unique selling point / unique feature', '[{"en":"Each product has a unique serial number.","zh-TW":"每個產品都有獨特的序號。"},{"en":"Our unique selling point is personalized service.","zh-TW":"我們的獨特賣點是個人化服務。"}]', '{"noun":"uniqueness","adjective":"unique","adverb":"uniquely"}', NULL, 2, 2094),
(2095, 'unit', '/ˈjuːnɪt/', 'noun', '{"zh-TW":["單位；部門"],"en":["an individual thing; a section of an organization"]}', NULL, 'business unit / per unit / unit cost', '[{"en":"The cost per unit decreased with higher volume.","zh-TW":"隨著產量增加，單位成本下降。"},{"en":"The marketing unit launched a new campaign.","zh-TW":"行銷部門推出了新活動。"}]', '{"noun":"unit, unity","verb":"unite","adjective":"united"}', NULL, 1, 2095),
(2096, 'universal', '/ˌjuːnɪˈvɜːrsl/', 'adjective', '{"zh-TW":["普遍的；全球的"],"en":["relating to all people or things"]}', NULL, 'universal access / universal standard / universal appeal', '[{"en":"The policy aims for universal access to healthcare.","zh-TW":"該政策旨在實現全民醫療保健。"},{"en":"Good customer service has universal appeal.","zh-TW":"良好的客戶服務具有普遍的吸引力。"}]', '{"noun":"universality","adjective":"universal","adverb":"universally"}', NULL, 3, 2096),
(2097, 'university', '/ˌjuːnɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["大學"],"en":["an institution of higher learning"]}', NULL, 'go to university / university degree', '[{"en":"She graduated from a top university.","zh-TW":"她從頂尖大學畢業。"},{"en":"Which university did you attend?","zh-TW":"你讀哪所大學？"}]', NULL, NULL, 4, 2097),
(2098, 'unprecedented', '/ʌnˈpresɪdentɪd/', 'adjective', '{"zh-TW":["前所未有的；空前的"],"en":["never done or known before"]}', NULL, 'unprecedented growth / unprecedented challenge / unprecedented demand', '[{"en":"The company experienced unprecedented demand.","zh-TW":"公司經歷了前所未有的需求。"},{"en":"We face unprecedented challenges in the market.","zh-TW":"我們在市場上面臨空前的挑戰。"}]', '{"adjective":"unprecedented, precedented"}', NULL, 5, 2098),
(2099, 'unveil', '/ʌnˈveɪl/', 'verb', '{"zh-TW":["揭露；公布"],"en":["to show or reveal something new"]}', NULL, 'unveil a plan / unveil a product / unveil a strategy', '[{"en":"The CEO unveiled the new product line at the conference.","zh-TW":"執行長在會議上公布了新產品線。"},{"en":"The government unveiled its economic recovery plan.","zh-TW":"政府公布了經濟復甦計畫。"}]', '{"verb":"unveil","noun":"unveiling"}', NULL, 2, 2099);
