(2107, 'urge', '/ɜːrdʒ/', 'verb, noun', '{"zh-TW":["敦促；催促","衝動"],"en":["to strongly encourage","a strong desire"]}', NULL, 'urge caution / strongly urge / urge someone to', '[{"en":"The board urged management to cut costs.","zh-TW":"董事會敦促管理層削減成本。"},{"en":"Experts urge companies to adopt sustainable practices.","zh-TW":"專家敦促企業採用永續做法。"}]', '{"noun":"urge, urgency","verb":"urge","adjective":"urgent"}', NULL, 1, 2107),
