(2109, 'usage', '/ˈjuːsɪdʒ/', 'noun', '{"zh-TW":["使用；用法"],"en":["the way something is used; the amount used"]}', NULL, 'energy usage / data usage / proper usage', '[{"en":"Monitor your data usage to avoid extra charges.","zh-TW":"監控您的數據使用量以避免額外費用。"},{"en":"Electricity usage peaks during summer months.","zh-TW":"用電量在夏季月份達到高峰。"}]', '{"noun":"usage, use","verb":"use"}', NULL, 2, 2109),
