(2112, 'vacancy', '/ˈveɪkənsi/', 'noun', '{"zh-TW":["空缺；職缺"],"en":["an unoccupied position or space"]}', NULL, 'job vacancy / fill a vacancy / vacancy rate', '[{"en":"There are several vacancies in the IT department.","zh-TW":"IT部門有幾個職缺。"},{"en":"The hotel vacancy rate dropped during the holiday.","zh-TW":"假期期間飯店空房率下降。"}]', '{"noun":"vacancy","adjective":"vacant"}', NULL, 3, 2112),
(2113, 'vacant', '/ˈveɪkənt/', 'adjective', '{"zh-TW":["空的；空缺的"],"en":["not occupied; empty"]}', NULL, 'vacant position / vacant lot / vacant office', '[{"en":"The position has been vacant for three months.","zh-TW":"這個職位已經空缺三個月了。"},{"en":"Several offices remain vacant in the building.","zh-TW":"大樓中有幾間辦公室仍然空著。"}]', '{"noun":"vacancy","adjective":"vacant","verb":"vacate"}', NULL, 2, 2113),
(2114, 'valid', '/ˈvælɪd/', 'adjective', '{"zh-TW":["有效的；正當的","有效的；合理的"],"en":["legally or logically acceptable","legally acceptable; logically sound"]}', '{"root":{"text":"val","meaning":"strong/worth (有力/有價值)"},"suffix":{"text":"-id","meaning":"being (…的)"},"logic":"有力量支撐的，即「有效的」。"}', 'valid passport / valid argument / valid reason; valid passport / valid point / valid until', '[{"en":"Your passport must be valid for at least six months.","zh-TW":"你的護照必須至少還有六個月效期。"},{"en":"That is a valid argument.","zh-TW":"那是一個正當的論點。"},{"en":"The coupon is valid until December 31.","zh-TW":"優惠券有效期至12月31日。"},{"en":"That''s a valid concern we should address.","zh-TW":"那是一個我們應該處理的合理顧慮。"}]', '{"noun":"validity","verb":"validate","adjective":"valid, invalid"}', NULL, 2, 2114),
