(2116, 'valuable', '/ˈvæljuəbl/', 'adjective', '{"zh-TW":["有價值的；貴重的"],"en":["worth a great deal; very useful"]}', NULL, 'valuable experience / valuable asset / valuable feedback', '[{"en":"Your feedback is extremely valuable to us.","zh-TW":"您的回饋對我們非常有價值。"},{"en":"Experienced employees are valuable assets.","zh-TW":"有經驗的員工是寶貴的資產。"}]', '{"noun":"value","adjective":"valuable, invaluable"}', NULL, 3, 2116),
(2117, 'valuation', '/ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["估值；估價"],"en":["the process of determining the worth of something"]}', NULL, 'company valuation / property valuation', '[{"en":"The startup''s valuation reached $1 billion.","zh-TW":"這家新創公司估值達到10億美元。"},{"en":"We ordered a property valuation.","zh-TW":"我們委託了不動產估價。"}]', '{"noun":"valuation","verb":"value","verb2":"valuate"}', NULL, 3, 2117),
(2118, 'value', '/ˈvæljuː/', 'noun, verb', '{"zh-TW":["價值；價格","重視；估價"],"en":["the importance or worth of something","to consider important"]}', NULL, 'added value / core values / market value', '[{"en":"The company''s core values include integrity and innovation.","zh-TW":"公司的核心價值包括誠信和創新。"},{"en":"We value our employees'' contributions.","zh-TW":"我們重視員工的貢獻。"}]', '{"noun":"value, valuation","verb":"value","adjective":"valuable"}', NULL, 2, 2118),
