(2121, 'variety', '/vəˈraɪəti/', 'noun', '{"zh-TW":["多樣性；種類"],"en":["a range of different things"]}', NULL, 'wide variety / variety of options / add variety', '[{"en":"We offer a wide variety of products.","zh-TW":"我們提供各式各樣的產品。"},{"en":"A variety of factors contributed to the success.","zh-TW":"多種因素促成了這次的成功。"}]', '{"noun":"variety","adjective":"various, varied","verb":"vary"}', NULL, 3, 2121),
(2122, 'various', '/ˈveriəs/', 'adjective', '{"zh-TW":["各種的；不同的"],"en":["several different types of"]}', NULL, 'various reasons / various options / various departments', '[{"en":"We explored various options before deciding.","zh-TW":"我們在決定前探索了各種選項。"},{"en":"The product is available in various sizes.","zh-TW":"該產品有各種尺寸。"}]', '{"adjective":"various","noun":"variety","verb":"vary"}', NULL, 3, 2122),
