(2124, 'vast', '/væst/', 'adjective', '{"zh-TW":["巨大的；廣闘的"],"en":["extremely large in area, size, or amount"]}', NULL, 'vast majority / vast amount / vast experience', '[{"en":"The vast majority of customers were satisfied.","zh-TW":"絕大多數客戶都感到滿意。"},{"en":"She has vast experience in international trade.","zh-TW":"她在國際貿易方面有豐富的經驗。"}]', '{"adjective":"vast","adverb":"vastly"}', NULL, 1, 2124),
(2125, 'vehicle', '/ˈviːɪkl/', 'noun', '{"zh-TW":["車輛；交通工具","媒介；手段"],"en":["a means of transport","a means of expressing ideas"]}', NULL, 'electric vehicle / company vehicle / investment vehicle', '[{"en":"Electric vehicles are gaining market share.","zh-TW":"電動車正在獲得市場佔有率。"},{"en":"The newsletter is a vehicle for company announcements.","zh-TW":"電子報是公司公告的媒介。"}]', '{"noun":"vehicle","adjective":"vehicular"}', NULL, 3, 2125),
(2126, 'vendor', '/ˈvendər/', 'noun', '{"zh-TW":["供應商；賣方"],"en":["a person or company that sells goods"]}', NULL, 'vendor management / preferred vendor / third-party vendor', '[{"en":"We are evaluating new vendors for the contract.","zh-TW":"我們正在評估新的供應商。"},{"en":"The vendor delivered the goods on time.","zh-TW":"供應商準時交付了貨物。"}]', '{"noun":"vendor"}', NULL, 2, 2126),
(2127, 'venture', '/ˈventʃər/', 'noun, verb', '{"zh-TW":["企業；冒險事業","冒險；敢於"],"en":["a risky business enterprise","to dare to do something risky"]}', NULL, 'joint venture / venture capital / new venture', '[{"en":"They launched a joint venture with a local partner.","zh-TW":"他們與當地合作夥伴成立了合資企業。"},{"en":"Venture capital funded the startup''s growth.","zh-TW":"風險投資資助了新創公司的成長。"}]', '{"noun":"venture, venturer","verb":"venture"}', NULL, 3, 2127),
