(2129, 'verdict', '/ˈvɜːrdɪkt/', 'noun', '{"zh-TW":["裁決；判決"],"en":["the decision made by a jury"]}', NULL, 'guilty verdict / reach a verdict', '[{"en":"The jury reached a verdict of not guilty.","zh-TW":"陪審團做出了無罪裁決。"},{"en":"The verdict was announced in court.","zh-TW":"裁決在法庭上宣布。"}]', NULL, NULL, 3, 2129),
(2130, 'verify', '/ˈverɪfaɪ/', 'verb', '{"zh-TW":["驗證；核實"],"en":["to confirm the truth or accuracy of"]}', '{"root":{"text":"ver","meaning":"true (真實)"},"suffix":{"text":"-ify","meaning":"使..."}}', 'verify information / verify identity / verify data', '[{"en":"Please verify the information before submitting.","zh-TW":"提交前請驗證資訊。"},{"en":"We need to verify the customer''s identity.","zh-TW":"我們需要核實客戶的身分。"}]', '{"noun":"verification","verb":"verify","adjective":"verifiable"}', NULL, 2, 2130),
(2131, 'versatile', '/ˈvɜːrsətl/', 'adjective', '{"zh-TW":["多功能的；多才多藝的"],"en":["able to adapt to many functions"]}', NULL, 'versatile tool / versatile employee / highly versatile', '[{"en":"The software is versatile enough for various tasks.","zh-TW":"這個軟體功能多樣，適用於各種任務。"},{"en":"She is a versatile team member.","zh-TW":"她是一位多才多藝的團隊成員。"}]', '{"noun":"versatility","adjective":"versatile"}', NULL, 3, 2131),
