(2133, 'veto', '/ˈviːtoʊ/', 'noun, verb', '{"zh-TW":["否決權；否決","否決"],"en":["the power to reject a decision","to reject or prohibit"]}', NULL, 'exercise a veto / veto power / veto a proposal', '[{"en":"The president vetoed the proposed legislation.","zh-TW":"總統否決了擬議的法案。"},{"en":"Shareholders have veto power over major decisions.","zh-TW":"股東對重大決策擁有否決權。"}]', '{"noun":"veto","verb":"veto"}', NULL, 1, 2133),
