(2137, 'violate', '/ˈvaɪəleɪt/', 'verb', '{"zh-TW":["違反；侵犯"],"en":["to break a law or agreement"]}', NULL, 'violate regulations / violate a contract / violate privacy', '[{"en":"The company violated environmental regulations.","zh-TW":"該公司違反了環境法規。"},{"en":"Sharing data without consent violates privacy laws.","zh-TW":"未經同意分享數據違反了隱私法。"}]', '{"noun":"violation","verb":"violate"}', NULL, 3, 2137),
(2138, 'virtual', '/ˈvɜːrtʃuəl/', 'adjective', '{"zh-TW":["虛擬的","虛擬的；實質上的"],"en":["created by computer; almost complete","existing in digital form; nearly as described"]}', NULL, 'virtual reality / virtual meeting; virtual meeting / virtual reality / virtual office', '[{"en":"We had a virtual meeting today.","zh-TW":"我們今天開了一場線上會議。"},{"en":"Virtual reality is becoming more popular.","zh-TW":"虛擬實境越來越受歡迎。"},{"en":"The team holds virtual meetings every Monday.","zh-TW":"團隊每週一舉行視訊會議。"},{"en":"Virtual reality is transforming training programs.","zh-TW":"虛擬實境正在改變培訓計畫。"}]', '{"adverb":"virtually","adjective":"virtual"}', NULL, 3, 2138),
(2139, 'virtue', '/ˈvɜːrtʃuː/', 'noun', '{"zh-TW":["美德；優點"],"en":["moral excellence; an advantage"]}', NULL, 'by virtue of / virtue of patience / corporate virtue', '[{"en":"By virtue of her experience, she was promoted.","zh-TW":"憑藉她的經驗，她獲得了升遷。"},{"en":"Patience is a virtue in negotiations.","zh-TW":"在談判中耐心是一種美德。"}]', '{"noun":"virtue","adjective":"virtuous"}', NULL, 2, 2139),
