(2142, 'vision', '/ˈvɪʒn/', 'noun', '{"zh-TW":["願景；眼光","視力"],"en":["an idea of what the future could be","the ability to see"]}', NULL, 'company vision / long-term vision / share a vision', '[{"en":"The CEO shared her vision for the company''s future.","zh-TW":"執行長分享了她對公司未來的願景。"},{"en":"A clear vision helps align team efforts.","zh-TW":"清晰的願景有助於統一團隊的努力方向。"}]', '{"noun":"vision, visionary","adjective":"visionary"}', NULL, 2, 2142),
(2143, 'vital', '/ˈvaɪtl/', 'adjective', '{"zh-TW":["至關重要的；不可或缺的"],"en":["absolutely necessary; essential"]}', NULL, 'vital role / vital importance / vital information', '[{"en":"Communication plays a vital role in teamwork.","zh-TW":"溝通在團隊合作中扮演至關重要的角色。"},{"en":"It is vital that we meet the deadline.","zh-TW":"我們必須在截止日前完成，這至關重要。"}]', '{"adjective":"vital","adverb":"vitally","noun":"vitality"}', NULL, 2, 2143),
(2144, 'volatile', '/ˈvɑːlətl/', 'adjective', '{"zh-TW":["波動的；不穩定的"],"en":["liable to change rapidly and unpredictably"]}', NULL, 'volatile market / volatile prices / highly volatile', '[{"en":"The stock market has been highly volatile this year.","zh-TW":"今年股市波動劇烈。"},{"en":"Oil prices remain volatile due to geopolitical tensions.","zh-TW":"由於地緣政治緊張，油價持續波動。"}]', '{"noun":"volatility","adjective":"volatile"}', NULL, 3, 2144),
(2145, 'volcano', '/vɒlˈkeɪnoʊ/', 'noun', '{"zh-TW":["火山"],"en":["a mountain that can erupt with lava and ash"]}', '{"root":{"text":"Vulcan","meaning":"Roman god of fire (火神)"},"logic":"以羅馬火神 Vulcan 命名。"}', 'active volcano / volcanic eruption', '[{"en":"The volcano erupted without warning.","zh-TW":"火山毫無預警地噴發。"},{"en":"Hawaii has several active volcanoes.","zh-TW":"夏威夷有幾座活火山。"}]', '{"adjective":"volcanic","noun":"volcanism"}', NULL, 3, 2145),
(2146, 'volume', '/ˈvɑːljuːm/', 'noun', '{"zh-TW":["量；體積","音量；冊"],"en":["the amount or quantity","the degree of loudness"]}', NULL, 'sales volume / high volume / trading volume', '[{"en":"Sales volume increased by 25% this year.","zh-TW":"今年銷售量增加了25%。"},{"en":"High-volume production reduces unit costs.","zh-TW":"大量生產降低了單位成本。"}]', '{"noun":"volume","adjective":"voluminous"}', NULL, 2, 2146),
