(2149, 'voucher', '/ˈvaʊtʃər/', 'noun', '{"zh-TW":["憑證；代金券"],"en":["a document that entitles the holder to a discount or service"]}', NULL, 'gift voucher / discount voucher / redeem a voucher', '[{"en":"Customers received a $10 gift voucher.","zh-TW":"顧客獲得了一張10美元的禮品券。"},{"en":"The voucher is valid for 30 days.","zh-TW":"該優惠券有效期為30天。"}]', '{"noun":"voucher"}', NULL, 3, 2149);
