(2154, 'warrant', '/ˈwɒrənt/', 'noun', '{"zh-TW":["搜索令；逮捕令","授權令；正當理由","保證；使有正當理由"],"en":["an official document allowing police action","a document authorizing action; justification","to justify; to guarantee"]}', NULL, 'search warrant / arrest warrant; warrant attention / arrest warrant / warrant further investigation', '[{"en":"Police obtained a search warrant.","zh-TW":"警方取得了搜索令。"},{"en":"There''s a warrant for his arrest.","zh-TW":"有一張對他的逮捕令。"},{"en":"The situation warrants immediate action.","zh-TW":"情況需要立即採取行動。"},{"en":"The findings warrant further investigation.","zh-TW":"這些發現值得進一步調查。"}]', '{"verb":"warrant","noun":"warrant, warranty"}', NULL, 3, 2154),
