(2156, 'waste', '/weɪst/', 'noun, verb', '{"zh-TW":["浪費；廢物","浪費"],"en":["unwanted material; extravagant use","to use carelessly"]}', NULL, 'waste of time / reduce waste / waste disposal', '[{"en":"The company reduced waste by 30% through recycling.","zh-TW":"公司透過回收減少了30%的廢物。"},{"en":"Don''t waste time on unnecessary meetings.","zh-TW":"不要把時間浪費在不必要的會議上。"}]', '{"noun":"waste, wastage","verb":"waste","adjective":"wasteful"}', NULL, 2, 2156),
