(2158, 'weather', '/ˈweðər/', 'noun', '{"zh-TW":["天氣"],"en":["the state of the atmosphere at a particular time"]}', '{"root":{"text":"weather","meaning":"wind/air (風/空氣)"},"logic":"源自古英語 weder（大氣狀態）。"}', 'weather forecast / bad weather / weather conditions', '[{"en":"What''s the weather like today?","zh-TW":"今天天氣如何？"},{"en":"Bad weather delayed our flight.","zh-TW":"惡劣天氣延誤了我們的航班。"}]', '{"verb":"weather"}', NULL, 3, 2158),
