(2161, 'whereas', '/werˈæz/', 'conjunction', '{"zh-TW":["然而；反之"],"en":["in contrast to the fact that"]}', NULL, 'whereas in fact / whereas previously', '[{"en":"Sales increased in Asia, whereas they declined in Europe.","zh-TW":"銷售在亞洲增長，而在歐洲則下降。"},{"en":"The old system was manual, whereas the new one is automated.","zh-TW":"舊系統是手動的，而新系統是自動化的。"}]', NULL, NULL, 3, 2161),
(2162, 'wholesale', '/ˈhoʊlseɪl/', 'noun', '{"zh-TW":["批發","批發的"],"en":["the selling of goods in large quantities at low prices","the selling of goods in large quantities","on a large scale"]}', '{"root":{"text":"whole","meaning":"whole (整體)"},"suffix":{"text":"sale","meaning":"sale (銷售)"},"logic":"整批銷售，即「批發」。"}', 'wholesale price / wholesale market; wholesale price / wholesale market / wholesale distributor', '[{"en":"They buy wholesale and sell retail.","zh-TW":"他們批發購入，零售賣出。"},{"en":"The wholesale price is much lower.","zh-TW":"批發價便宜很多。"},{"en":"We buy materials at wholesale prices.","zh-TW":"我們以批發價購買材料。"},{"en":"The wholesale market opens at 5 AM.","zh-TW":"批發市場凌晨5點開門。"}]', '{"noun":"wholesaler","adjective":"wholesale"}', NULL, 3, 2162),
