(2165, 'willing', '/ˈwɪlɪŋ/', 'adjective', '{"zh-TW":["願意的；樂意的"],"en":["ready or eager to do something"]}', NULL, 'willing to / willing participant / willing and able', '[{"en":"Are you willing to relocate for the job?","zh-TW":"你願意為這份工作搬遷嗎？"},{"en":"We need willing participants for the pilot program.","zh-TW":"我們需要願意參加試驗計畫的人。"}]', '{"noun":"willingness","adjective":"willing, unwilling","adverb":"willingly"}', NULL, 3, 2165),
