(2170, 'withstand', '/wɪðˈstænd/', 'verb', '{"zh-TW":["承受；抵抗"],"en":["to remain undamaged by; to resist"]}', NULL, 'withstand pressure / withstand competition / withstand scrutiny', '[{"en":"The company withstood intense market competition.","zh-TW":"公司經受住了激烈的市場競爭。"},{"en":"The product is designed to withstand extreme conditions.","zh-TW":"該產品設計為可承受極端條件。"}]', '{"verb":"withstand"}', NULL, 3, 2170),
