(2174, 'worth', '/wɜːrθ/', 'noun, adjective', '{"zh-TW":["價值","值得的"],"en":["the value of something","deserving of"]}', NULL, 'worth mentioning / net worth / worth the effort', '[{"en":"The investment is definitely worth the risk.","zh-TW":"這項投資絕對值得冒險。"},{"en":"The company''s net worth exceeded $1 billion.","zh-TW":"公司淨值超過了10億美元。"}]', '{"noun":"worth","adjective":"worth, worthy, worthwhile"}', NULL, 2, 2174),
(2175, 'worthwhile', '/ˌwɜːrθˈwaɪl/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["worth the time, money, or effort spent"]}', NULL, 'worthwhile investment / worthwhile endeavor / make it worthwhile', '[{"en":"The training program proved to be a worthwhile investment.","zh-TW":"培訓計畫被證明是一項值得的投資。"},{"en":"It''s worthwhile to compare prices before purchasing.","zh-TW":"購買前比較價格是值得的。"}]', '{"adjective":"worthwhile, worthy","noun":"worth"}', NULL, 4, 2175),
(2176, 'worthy', '/ˈwɜːrði/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["deserving respect or attention"]}', NULL, 'worthy of / worthy cause / noteworthy', '[{"en":"The proposal is worthy of consideration.","zh-TW":"這個提案值得考慮。"},{"en":"They donated to a worthy cause.","zh-TW":"他們為一項有價值的事業捐款。"}]', '{"noun":"worth, worthiness","adjective":"worthy, unworthy, noteworthy"}', NULL, 2, 2176),
(2177, 'yield', '/jiːld/', 'verb, noun', '{"zh-TW":["產生；讓步","產量；收益"],"en":["to produce; to give way","the amount produced; return on investment"]}', NULL, 'yield results / high yield / yield to pressure', '[{"en":"The investment yielded a 12% annual return.","zh-TW":"這項投資產生了12%的年報酬率。"},{"en":"The new strategy is expected to yield positive results.","zh-TW":"新策略預計將產生正面的結果。"}]', '{"noun":"yield","verb":"yield"}', NULL, 2, 2177),
(2178, 'zone', '/zoʊn/', 'noun', '{"zh-TW":["地帶；區域"],"en":["an area with particular characteristics"]}', NULL, 'time zone / free trade zone / comfort zone', '[{"en":"The factory is located in a free trade zone.","zh-TW":"工廠位於自由貿易區。"},{"en":"Employees should step out of their comfort zones.","zh-TW":"員工應該走出舒適圈。"}]', '{"noun":"zone, zoning","verb":"zone"}', NULL, 1, 2178);
